(* Closed list of original declaration indices, in the actual link order.
   Only identifiers are evaluated. The checked tables use named C bodies. *)
Require Import VST.floyd.proofauto CCV.ccv_core CCV.ccv_primitives CCV.CCLinkedProgram.
Import ListNotations.
Fixpoint decl_number (i:ident)(xs:list ident):nat :=
 match xs with []=>O | x::tail=>if Pos.eqb i x then O else S(decl_number i tail) end.
Definition named_ids:list ident := [ccv_core.___compcert_va_int32;ccv_core.___compcert_va_int64;ccv_core.___compcert_va_float64;ccv_core.___compcert_va_composite;ccv_core.___compcert_i64_dtos;ccv_core.___compcert_i64_dtou;ccv_core.___compcert_i64_stod;ccv_core.___compcert_i64_utod;ccv_core.___compcert_i64_stof;ccv_core.___compcert_i64_utof;ccv_core.___compcert_i64_sdiv;ccv_core.___compcert_i64_udiv;ccv_core.___compcert_i64_smod;ccv_core.___compcert_i64_umod;ccv_core.___compcert_i64_shl;ccv_core.___compcert_i64_shr;ccv_core.___compcert_i64_sar;ccv_core.___compcert_i64_smulh;ccv_core.___compcert_i64_umulh;ccv_core.___builtin_ais_annot;ccv_core.___builtin_bswap64;ccv_core.___builtin_bswap;ccv_core.___builtin_bswap32;ccv_core.___builtin_bswap16;ccv_core.___builtin_clz;ccv_core.___builtin_clzl;ccv_core.___builtin_clzll;ccv_core.___builtin_ctz;ccv_core.___builtin_ctzl;ccv_core.___builtin_ctzll;ccv_core.___builtin_fabs;ccv_core.___builtin_fabsf;ccv_core.___builtin_fsqrt;ccv_core.___builtin_sqrt;ccv_core.___builtin_memcpy_aligned;ccv_core.___builtin_sel;ccv_core.___builtin_annot;ccv_core.___builtin_annot_intval;ccv_core.___builtin_membar;ccv_core.___builtin_va_start;ccv_core.___builtin_va_arg;ccv_core.___builtin_va_copy;ccv_core.___builtin_va_end;ccv_core.___builtin_unreachable;ccv_core.___builtin_expect;ccv_core.___builtin_fmax;ccv_core.___builtin_fmin;ccv_core.___builtin_fmadd;ccv_core.___builtin_fmsub;ccv_core.___builtin_fnmadd;ccv_core.___builtin_fnmsub;ccv_core.___builtin_read16_reversed;ccv_core.___builtin_read32_reversed;ccv_core.___builtin_write16_reversed;ccv_core.___builtin_write32_reversed;ccv_core.___builtin_debug;ccv_primitives._ccv_ceil_div;ccv_primitives._ccv_weight;ccv_core._shape;ccv_core._validate;ccv_core._clear;ccv_core._toggle;ccv_core._nontrivial;ccv_core._restore;ccv_core._forbid;ccv_core._overlap;ccv_core._bounds;ccv_core._leaf;ccv_core._search;ccv_core._stats_init;ccv_core._ccv_decide;ccv_core._ccv_distance;ccv_primitives._ccv_bit_xor;ccv_primitives._ccv_dot;ccv_primitives._ccv_toggle].
Definition original_order:list nat:=ltac:(let v:=eval vm_compute in (map (fun i=>decl_number i named_ids) (map fst (prog_funct linked_prog))) in exact v).
Print original_order.
